<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, nextTick, watch, ref } from 'vue';
import { mdiViewDashboardOutline, mdiMemory, mdiLan, mdiDesktopTowerMonitor, mdiHarddisk, mdiDatabaseOutline, mdiPlus, mdiMagnify, mdiArrowTopRight, mdiArrowLeft, mdiDownload, mdiUpload, mdiCheckCircleOutline, mdiAlertCircleOutline, mdiClose, mdiContentCopy, mdiTrashCanOutline, mdiCubeOutline, mdiArrowRight, mdiCogOutline, mdiRefresh, mdiCheck, mdiChevronRight, mdiServerOutline, mdiInformationOutline } from '@mdi/js';
import type { Category, Component, Configuration, Database, InventoryPC, Placement, Specs, System } from '../shared/types';
import { categories } from '../shared/types';
import { checkConfiguration } from '../shared/compatibility';
import { stockReadiness, installedConfiguration } from '../shared/inventory';
import InventoryWorkspace from './InventoryWorkspace.vue';
import InstallationsWorkspace from './InstallationsWorkspace.vue';
import {locationPath} from '../shared/installations';
import {resolveRequirementVersion} from '../shared/compatibility';
import EngineeringEditor from './EngineeringEditor.vue';
import BayEditor from './BayEditor.vue';
import { catalogSuggestions, normalizeCatalogValue, normalizeCatalogValues, catalogNumericValuesRule, catalogComponentArrayRule } from '../shared/catalog-options';
import { connectionPortTotals, connectionSummary, portLabel } from '../shared/ports';
import PcLifecycleEditor from './PcLifecycleEditor.vue';
const db=ref<Database>({components:[],systems:[],configurations:[],pcs:[],inventory:[],requirementsSets:[],installationLocations:[]});
const installationsWorkspace=ref<{hasUnsavedChanges:()=>boolean;confirmDiscard:()=>boolean}|null>(null);
const inventoryWorkspace=ref<{hasUnsavedChanges:()=>boolean;confirmDiscard:()=>boolean}|null>(null);
const recoveryRequired=ref(false);
const revision=ref(''), editorRevision=ref(''), configRevision=ref(''), editorOriginal=ref('');
const restoreFile=ref<File|null>(null), restorePreview=ref<{counts:Record<string,number>;revision:string}|null>(null), restoreBackup=ref<unknown>(null), spreadsheetSafe=ref(true);
const loading=ref(true), failure=ref(''), busy=ref(false), notice=ref(''), noticeOpen=ref(false);
const page=ref('Configurations'), search=ref(''), filter=ref('All configurations'), categoryFilter=ref('All components');
const working=ref<Configuration|null>(null), original=ref(''), detailTab=ref('components');
const componentDraft=ref<Component|null>(null), systemDraft=ref<System|null>(null), pcDraft=ref<InventoryPC|null>(null);
const dialogOpeners=new Map<string,HTMLElement>();
for(const [name,draft] of Object.entries({componentDraft,systemDraft,pcDraft}))watch(draft,(value,old)=>{if(value&&!old&&document.activeElement instanceof HTMLElement)dialogOpeners.set(name,document.activeElement);if(!value&&old)nextTick(()=>{const opener=dialogOpeners.get(name);if(opener?.isConnected)opener.focus();else document.getElementById('main-content')?.focus();dialogOpeners.delete(name);});},{flush:'sync'});
const jsonSpecs=ref(''), advanced=ref(false), confirmDelete=ref<{collection:string;id:string;name:string}|null>(null);
watch(confirmDelete,(value,old)=>{if(value&&!old&&document.activeElement instanceof HTMLElement)dialogOpeners.set('delete',document.activeElement);if(!value&&old)nextTick(()=>{const opener=dialogOpeners.get('delete');if(opener?.isConnected)opener.focus();else document.getElementById('main-content')?.focus();dialogOpeners.delete('delete');});},{flush:'sync'});
const addCategory=ref<Category>('Scientific card'), addPart=ref(''), addQty=ref(1);
const csvCollection=ref('components'), importFile=ref<File|null>(null), importing=ref(false);
const navigation=[{name:'Configurations',icon:mdiViewDashboardOutline},{name:'Component catalog',icon:mdiMemory},{name:'Component inventory',icon:mdiCubeOutline},{name:'Equipment systems',icon:mdiLan},{name:'PC inventory',icon:mdiDesktopTowerMonitor},{name:'Storage planner',icon:mdiHarddisk},{name:'Installations',icon:mdiLan}];
const uid=()=>crypto.randomUUID();
const clone=<T,>(v:T):T=>v===undefined?v:JSON.parse(JSON.stringify(v));
function toast(text:string){notice.value=text;noticeOpen.value=true;}
async function api(url:string,options:RequestInit={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});const result=await r.json();if(!r.ok)throw Error(result.error||'Request failed');const next=r.headers.get('X-Workspace-Revision');if(next)revision.value=next;return result;}
async function load(){try{const state=await api('/api/state');revision.value=state.revision;recoveryRequired.value=!!state.recoveryRequired;const {revision:_,recoveryRequired:__,...data}=state;db.value=data;failure.value='';}catch(e){failure.value=String(e);}finally{loading.value=false;}}
async function saveRecord(collection:string,record:{id:string},expected=editorRevision.value){busy.value=true;try{await api(`/api/${collection}/${record.id}`,{method:'PUT',headers:{'If-Match':expected},body:JSON.stringify(record)});await load();if(collection!=='configurations'&&configRevision.value===expected)configRevision.value=revision.value;return true;}catch(e){toast(String(e));return false;}finally{busy.value=false;}}
function navigate(name:string){if(installationsWorkspace.value&&!installationsWorkspace.value.confirmDiscard())return;if(inventoryWorkspace.value&&!inventoryWorkspace.value.confirmDiscard())return;if(working.value&&dirty.value&&!window.confirm('Discard unsaved configuration changes?'))return;page.value=name;working.value=null;search.value='';nextTick(()=>document.getElementById('main-content')?.focus());}
const dirty=computed(()=>!!working.value&&JSON.stringify(working.value)!==original.value);
function openConfig(c:Configuration){configRevision.value=revision.value;working.value=clone(c);original.value=JSON.stringify(c);detailTab.value='components';page.value='Configurations';}
function newConfig(){const c:Configuration={id:uid(),name:'Untitled configuration',description:'',systemId:'',status:'Draft',updatedAt:new Date().toISOString(),placements:[],storage:{raid:'none',bootMirror:false},notes:''};openConfig(c);original.value='';}
function duplicate(c:Configuration){const copy=clone(c);delete copy.revision;delete copy.approvalSnapshot;delete copy.approvalHistory;copy.id=uid();copy.name=`${c.name} · copy`;copy.status='Draft';copy.updatedAt=new Date().toISOString();openConfig(copy);original.value='';}
async function saveConfig(){if(!working.value)return;if(working.value.status==='Approved'&&report.value?.findings.some(f=>f.severity==='error'))return toast('Resolve compatibility conflicts before marking this configuration Approved.');working.value.updatedAt=new Date().toISOString();if(await saveRecord('configurations',working.value,configRevision.value)){working.value=clone(db.value.configurations.find(c=>c.id===working.value?.id)!);original.value=JSON.stringify(working.value);configRevision.value=revision.value;toast('Configuration saved.');}}
const pcSettingsConfiguration=computed(()=>{const pc=pcDraft.value;if(!pc?.buildSettings)return null;return {...installedConfiguration(pc,db.value),storage:pc.buildSettings.storage,portMappings:pc.buildSettings.portMappings,software:pc.software};});
const report=computed(()=>working.value?checkConfiguration(working.value,db.value):null);
const stockAvailability=computed(()=>working.value?stockReadiness(working.value,db.value):[]);
const reports=computed(()=>Object.fromEntries(db.value.configurations.map(c=>[c.id,checkConfiguration(c,db.value)])));
const configs=computed(()=>db.value.configurations.filter(c=>(c.name+' '+c.description+' '+systemName(c.systemId)).toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='All configurations'||(filter.value==='Conflicts'?reports.value[c.id]?.status==='Conflicts':c.status===filter.value))));
const components=computed(()=>db.value.components.filter(c=>(c.name+' '+c.manufacturer).toLowerCase().includes(search.value.toLowerCase())&&(categoryFilter.value==='All components'||c.category===categoryFilter.value)));
const systems=computed(()=>db.value.systems.filter(s=>(s.name+' '+s.location).toLowerCase().includes(search.value.toLowerCase())));
const pcs=computed(()=>db.value.pcs.filter(p=>(p.name+' '+p.serial+' '+p.location).toLowerCase().includes(search.value.toLowerCase())));
const conflictCount=computed(()=>Object.values(reports.value).filter(r=>r.status==='Conflicts').length);
const availableParts=computed(()=>db.value.components.filter(c=>c.category===addCategory.value));
const linkedSystem=computed(()=>{const version=working.value&&resolveRequirementVersion(working.value,db.value);return version?{id:working.value!.requirementSetId||'',name:version.name,description:version.description,location:'',connections:version.connections}:db.value.systems.find(s=>s.id===working.value?.systemId);});
const selectedDrives=computed(()=>working.value?.placements.filter(p=>part(p.componentId)?.category==='Drive')||[]);
const selectedCards=computed(()=>working.value?.placements.filter(p=>['GPU','Scientific card','Network card','Storage adapter'].includes(part(p.componentId)?.category||''))||[]);
const slots=computed(()=>part(working.value?.placements.find(p=>part(p.componentId)?.category==='Motherboard')?.componentId||'')?.specs.slots||[]);
function part(id:string){return db.value.components.find(c=>c.id===id);}
function systemName(id:string){return db.value.systems.find(s=>s.id===id)?.name||'No equipment linked';}
function configName(id:string){return db.value.configurations.find(c=>c.id===id)?.name||'Unassigned';}
function errors(id:string){return reports.value[id]?.findings.filter(f=>f.severity==='error').length||0;}
function quantity(c:Configuration){return c.placements.reduce((n,p)=>n+p.quantity,0);}
function capacity(n:number){return n>=1000?`${+(n/1000).toFixed(2)} TB`:`${n} GB`;}
function summary(c:Component){const s=c.specs;switch(c.category){case 'Chassis':return `${s.supportedForms?.join(' / ')||'Form unknown'} · ${s.hotSwapBays??'?'} hot-swap bays`;case 'Motherboard':return `${s.socket||'?'} · ${s.formFactor||'?'} · ${s.slots?.length??'?'} expansion slots`;case 'CPU':return `${s.socket||'Socket unknown'} · ${s.powerW??'?'} W`;case 'Memory':return `${s.capacityGb??'?'} GB · ${s.memoryType||'Type unknown'}`;case 'Drive':return `${capacity(s.capacityGb||0)} · ${s.driveInterface||'?'} · ${s.driveSize||'?'}`;case 'PSU':return `${s.capacityW??'?'} W · ${s.sataPower??'?'} SATA plugs`;case 'Cooler':return `${s.heightMm??'?'} mm · ${s.supportsSockets?.join(', ')||'Socket unknown'}`;default:return `${s.slotBus||'?'} x${s.slotWidth||'?'} · ${s.requiredLanes||'?'} lanes · ${s.lengthMm??'?'} mm`;}}
function addComponent(){if(!working.value||!addPart.value)return;working.value.placements.push({id:uid(),componentId:addPart.value,quantity:addQty.value,slotId:'',role:part(addPart.value)?.category==='Drive'?'data':'general',mount:'auto',group:''});addPart.value='';addQty.value=1;}
function splitPlacement(p:Placement){if(!working.value||p.quantity<2)return;const rows=Array.from({length:p.quantity},()=>({...clone(p),id:uid(),quantity:1,slotId:'',targetId:''}));const i=working.value.placements.findIndex(x=>x.id===p.id);working.value.placements.splice(i,1,...rows);}
function removePlacement(id:string){if(working.value)working.value.placements=working.value.placements.filter(p=>p.id!==id);}
const specFields:Record<Category,{key:keyof Specs;label:string;kind?:'text'|'list'|'select'|'bool';items?:string[]}[]>={
 'Chassis':[{key:'supportedForms',label:'Supported board forms',kind:'list'},{key:'rearSlots',label:'Rear bracket positions'},{key:'maxCardLengthMm',label:'Card length clearance (mm)'},{key:'maxCardHeightMm',label:'Card height clearance (mm)'},{key:'maxCoolerHeightMm',label:'Cooler height clearance (mm)'},{key:'bays25',label:'Internal 2.5-inch bays'},{key:'bays35',label:'Internal 3.5-inch bays'},{key:'bays525',label:'External 5.25-inch bays'},{key:'hotSwapBays',label:'Separate front hot-swap bays'},{key:'lengthMm',label:'Length (mm)'},{key:'heightMm',label:'Height (mm)'},{key:'widthMm',label:'Width (mm)'}],
 'Motherboard':[{key:'socket',label:'CPU socket',kind:'text'},{key:'formFactor',label:'Form factor',kind:'select',items:['ATX','Micro-ATX','Mini-ITX','E-ATX']},{key:'memoryType',label:'Memory type',kind:'select',items:['DDR3','DDR4','DDR5']},{key:'dimmSlots',label:'DIMM slots'},{key:'maxMemoryGb',label:'Maximum memory (GB)'},{key:'usbA',label:'Usable external USB-A ports'},{key:'usbC',label:'Usable external USB-C ports'},{key:'ethernet',label:'Ethernet ports'},{key:'sataPorts',label:'SATA ports'},{key:'m2Slots',label:'NVMe M.2 slots'},{key:'m2Lengths',label:'M.2 lengths (mm)',kind:'list'},{key:'bifurcation',label:'PCIe bifurcation supported',kind:'bool'},{key:'powerW',label:'Estimated power (W)'}],
 'CPU':[{key:'socket',label:'CPU socket',kind:'text'},{key:'powerW',label:'Maximum power estimate (W)'}],
 'Memory':[{key:'memoryType',label:'Memory type',kind:'select',items:['DDR3','DDR4','DDR5']},{key:'capacityGb',label:'Capacity per module (GB)'},{key:'powerW',label:'Power per module (W)'}],
 'GPU':[], 'Scientific card':[], 'Network card':[], 'Storage adapter':[], 'Bay accessory':[{key:'powerW',label:'Estimated power (W)'},{key:'lengthMm',label:'Depth (mm)'},{key:'heightMm',label:'Height (mm)'},{key:'widthMm',label:'Width (mm)'}],
 'Drive':[{key:'capacityGb',label:'Capacity per drive (GB)'},{key:'driveInterface',label:'Interface',kind:'select',items:['SATA','NVMe']},{key:'driveSize',label:'Form factor',kind:'select',items:['2.5','3.5','M.2']},{key:'m2Length',label:'M.2 length (mm)'},{key:'powerW',label:'Power per drive (W)'}],
 'PSU':[{key:'capacityW',label:'Rated power (W)'},{key:'sataPower',label:'SATA power plugs'},{key:'formFactor',label:'PSU form factor',kind:'text'}],
 'Cooler':[{key:'heightMm',label:'Height (mm)'},{key:'supportsSockets',label:'Supported sockets',kind:'list'},{key:'powerW',label:'Power (W)'}]
};
const cardFields:typeof specFields['GPU']=[{key:'slotBus',label:'Slot bus',kind:'select',items:['PCI','PCIe']},{key:'slotWidth',label:'Physical connector width (x)'},{key:'requiredLanes',label:'Required electrical lanes'},{key:'minGeneration',label:'Minimum PCIe generation'},{key:'bracketWidth',label:'Rear bracket positions used'},{key:'lengthMm',label:'Length (mm)'},{key:'heightMm',label:'Height (mm)'},{key:'widthMm',label:'Width (mm)'},{key:'powerW',label:'Estimated power (W)'}];
const currentFields=computed(()=>{if(!componentDraft.value)return [];const c=componentDraft.value.category;return [...(specFields[c].length?specFields[c]:c==='Storage adapter'&&componentDraft.value.specs.baySize&&!componentDraft.value.specs.slotBus?[{key:'slotBus' as const,label:'Expansion slot bus (only if also slot-mounted)',kind:'select' as const,items:['PCI','PCIe']},{key:'sataPorts' as const,label:'Controller SATA data ports (if active controller)'},{key:'powerW' as const,label:'Estimated power (W)'},{key:'lengthMm' as const,label:'Depth (mm)'}]:cardFields),...(c==='Network card'?[{key:'ethernet' as const,label:'Ethernet ports added'}]:[]),...(c==='Storage adapter'?[{key:'sledDrives' as const,label:'NVMe drive positions'},{key:'requiresBifurcation' as const,label:'Requires lane bifurcation',kind:'bool' as const},{key:'sledHotSwap' as const,label:'Vendor supports live hot-swap',kind:'bool' as const}]:[])];});
function specValue(key:keyof Specs){const v=componentDraft.value?.specs[key];return v;}
function specListValue(key:keyof Specs){const v=componentDraft.value?.specs[key];return Array.isArray(v)?v.filter((item):item is string|number=>typeof item==='string'||typeof item==='number'):[];}
function specText(key:keyof Specs){const v=specValue(key);return v===undefined?undefined:String(v);}
function fieldSuggestions(key:keyof Specs){return catalogSuggestions(db.value,key);}
function setSpec(key:keyof Specs,value:unknown,kind?:string){if(!componentDraft.value)return;const specs=componentDraft.value.specs as Record<string,unknown>;if(value===''||value===null||value===undefined){delete specs[key];return;}if(kind==='list'){try{const values=normalizeCatalogValues(value,fieldSuggestions(key),{numeric:key==='m2Lengths'});if(values.length)specs[key]=values;else delete specs[key];}catch{specs[key]=value;}}else specs[key]=kind==='bool'?!!value:kind==='text'||kind==='select'?normalizeCatalogValue(value,fieldSuggestions(key)):Number(value);}

function editComponent(c?:Component){editorRevision.value=revision.value;componentDraft.value=c?clone(c):{id:uid(),name:'',category:'Scientific card',manufacturer:'',specs:{},source:'',verified:false};advanced.value=false;jsonSpecs.value=JSON.stringify(componentDraft.value.specs,null,2);editorOriginal.value=JSON.stringify(componentDraft.value);}
function changeCategory(){if(componentDraft.value)componentDraft.value.specs={};advanced.value=false;}
function toggleAdvanced(){if(!componentDraft.value)return;if(!advanced.value)jsonSpecs.value=JSON.stringify(componentDraft.value.specs,null,2);else {try{componentDraft.value.specs=JSON.parse(jsonSpecs.value);}catch{return toast('Specifications must be valid JSON.');}}advanced.value=!advanced.value;}
async function saveComponent(){if(!componentDraft.value)return;try{if(advanced.value)componentDraft.value.specs=JSON.parse(jsonSpecs.value);const arrayValidation=catalogComponentArrayRule(componentDraft.value.specs);if(arrayValidation!==true)return toast(arrayValidation);if(await saveRecord('components',componentDraft.value)){componentDraft.value=null;toast('Component saved.');}}catch(e){toast(String(e));}}
function addSlot(){if(componentDraft.value){const s=componentDraft.value.specs;s.slots??=[];let n=1;while(s.slots.some(slot=>slot.id===`SLOT_${n}`))n++;let position=1;while(s.slots.some(slot=>slot.position===position))position++;s.slots.push({id:`SLOT_${n}`,bus:'PCIe',physical:16,lanes:4,generation:3,position});}}
function editSystem(s?:System){editorRevision.value=revision.value;systemDraft.value=s?clone(s):{id:uid(),name:'',location:'',description:'',connections:[]};editorOriginal.value=JSON.stringify(systemDraft.value);}
function addConnection(){systemDraft.value?.connections.push({id:uid(),name:'',usbA:0,usbC:0,ethernet:0,notes:''});}
async function saveSystem(){if(systemDraft.value&&await saveRecord('systems',systemDraft.value)){systemDraft.value=null;toast('Equipment system saved.');}}
function editPC(p?:InventoryPC){editorRevision.value=revision.value;pcDraft.value=p?clone(p):{id:uid(),name:'',serial:'',location:'',configurationId:'',notes:'',buildSettings:null};pcDraft.value.software??=clone(pcDraft.value.buildSettings?.software||{});if(pcDraft.value.buildSettings){const settings=installedConfiguration(pcDraft.value,db.value);pcDraft.value.buildSettings.portMappings=settings.portMappings||[];if(settings.storage.groups)pcDraft.value.buildSettings.storage.groups=settings.storage.groups;}editorOriginal.value=JSON.stringify(pcDraft.value);}
function captureTemplateSettings(copySoftware=true){const cfg=db.value.configurations.find(c=>c.id===pcDraft.value?.configurationId);if(pcDraft.value&&cfg){if(copySoftware||!pcDraft.value.software||!Object.keys(pcDraft.value.software).length)pcDraft.value.software=clone(cfg.software||{});pcDraft.value.buildSettings={systemId:cfg.systemId,storage:clone(cfg.storage),notes:cfg.notes,software:clone(cfg.software||{}),portMappings:clone(cfg.portMappings||[]),requirementSetId:cfg.requirementSetId,requirementRevision:cfg.requirementRevision,requirementSnapshot:clone(cfg.requirementSnapshot)};if(db.value.inventory.some(s=>s.allocations.some(a=>a.pcId===pcDraft.value?.id&&a.state==='installed')))pcDraft.value.buildSettings.portMappings=installedConfiguration(pcDraft.value,db.value).portMappings||[];}}
async function savePC(){if(pcDraft.value&&!db.value.pcs.some(p=>p.id===pcDraft.value?.id)&&!pcDraft.value.buildSettings)captureTemplateSettings(false);if(pcDraft.value&&await saveRecord('pcs',pcDraft.value)){pcDraft.value=null;toast('PC saved.');}}
async function deleteRecord(){if(!confirmDelete.value)return;busy.value=true;try{await api(`/api/${confirmDelete.value.collection}/${confirmDelete.value.id}`,{method:'DELETE',headers:{'If-Match':revision.value}});await load();if(working.value?.id===confirmDelete.value.id)working.value=null;confirmDelete.value=null;toast('Record deleted.');}catch(e){toast(String(e));}finally{busy.value=false;}}
async function importCSV(){if(!importFile.value)return;importing.value=true;try{const result=await api(`/api/${csvCollection.value}/import`,{method:'POST',headers:{'If-Match':revision.value},body:JSON.stringify({csv:await importFile.value.text()})});await load();toast(`Imported ${result.imported} records. Matching IDs updated.`);importFile.value=null;}catch(e){toast(String(e));}finally{importing.value=false;}}

const editorDirty=computed(()=>{const d=componentDraft.value||systemDraft.value||pcDraft.value;return !!d&&(JSON.stringify(d)!==editorOriginal.value||(advanced.value&&!!componentDraft.value&&jsonSpecs.value!==JSON.stringify(componentDraft.value.specs,null,2)));});
function closeEditor(kind:'component'|'system'|'pc'){if(editorDirty.value&&!window.confirm('Discard unsaved changes?'))return;if(kind==='component')componentDraft.value=null;else if(kind==='system')systemDraft.value=null;else pcDraft.value=null;}
async function refreshWorkspace(){if(installationsWorkspace.value&&!installationsWorkspace.value.confirmDiscard())return;if(inventoryWorkspace.value&&!inventoryWorkspace.value.confirmDiscard())return;if((dirty.value||editorDirty.value)&&!window.confirm('Discard drafts and reload the workspace?'))return;working.value=null;componentDraft.value=null;systemDraft.value=null;pcDraft.value=null;await load();}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value||editorDirty.value||inventoryWorkspace.value?.hasUnsavedChanges()||installationsWorkspace.value?.hasUnsavedChanges()){e.preventDefault();e.returnValue='';}}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
async function previewRestore(){try{if(!restoreFile.value)return;restoreBackup.value=JSON.parse(await restoreFile.value.text());restorePreview.value=await api('/api/restore/preview',{method:'POST',body:JSON.stringify({backup:restoreBackup.value})});}catch(e){toast(String(e));restorePreview.value=null;}}
async function commitRestore(){if(!restorePreview.value)return;if(!window.confirm('Replace the entire workspace with this backup? A safety backup will be saved first.'))return;busy.value=true;try{const result=await api('/api/restore',{method:'POST',headers:{'If-Match':restorePreview.value.revision},body:JSON.stringify({backup:restoreBackup.value})});await load();restorePreview.value=null;restoreFile.value=null;toast(`Workspace restored. Safety backup: ${result.backupFile}`);}catch(e){toast(String(e));}finally{busy.value=false;}}


const requirementChoices=computed(()=>[{title:'No installation requirements linked',value:''},...db.value.requirementsSets.filter(s=>s.versions.length).map(s=>({title:s.name,value:s.id}))]);
function requirementRevisions(id:string){return db.value.requirementsSets.find(s=>s.id===id)?.versions.map(v=>({title:`Revision ${v.revision} · ${v.name}`,value:v.revision}))||[];}
function selectConfigRequirements(){if(!working.value)return;working.value.requirementRevision=db.value.requirementsSets.find(s=>s.id===working.value!.requirementSetId)?.versions.at(-1)?.revision||0;updateConfigRequirements();}
function updateConfigRequirements(){if(!working.value)return;const selected=db.value.requirementsSets.find(s=>s.id===working.value!.requirementSetId)?.versions.find(v=>v.revision===working.value!.requirementRevision);if(selected)working.value.requirementSnapshot=clone(selected);else delete working.value.requirementSnapshot;}
function selectPCRequirements(){if(!pcDraft.value?.buildSettings)return;const settings=pcDraft.value.buildSettings;settings.requirementRevision=db.value.requirementsSets.find(s=>s.id===settings.requirementSetId)?.versions.at(-1)?.revision||0;updatePCRequirements();}
function updatePCRequirements(){if(!pcDraft.value?.buildSettings)return;const settings=pcDraft.value.buildSettings;const version=db.value.requirementsSets.find(s=>s.id===settings.requirementSetId)?.versions.find(v=>v.revision===settings.requirementRevision);if(version)settings.requirementSnapshot=clone(version);else delete settings.requirementSnapshot;}
function selectPCLocation(){if(!pcDraft.value)return;const location=db.value.installationLocations.find(l=>l.id===pcDraft.value!.installationLocationId);if(location&&!pcDraft.value.configurationId)pcDraft.value.configurationId=location.targetConfigurationId;}

function labelWorkspaceTables(){for(const table of document.querySelectorAll<HTMLElement>('[data-workspace-table]')){const name=table.dataset.workspaceTable!;table.querySelector('table')?.setAttribute('aria-label',name);const wrapper=table.querySelector<HTMLElement>('.v-table__wrapper');if(wrapper){wrapper.setAttribute('tabindex','0');wrapper.setAttribute('role','region');wrapper.setAttribute('aria-label',`${name}; scroll to view all columns`);}}}
const vWorkspaceTable={mounted:()=>nextTick(labelWorkspaceTables),updated:()=>nextTick(labelWorkspaceTables)};
onMounted(async()=>{await load();const context=(document as Document&{modelContext?:{registerTool:(t:unknown)=>Promise<void>}}).modelContext;if(context){for(const tool of [{name:'list_configurations',description:'Read saved PC configurations and compatibility summaries.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>db.value.configurations.map(c=>({id:c.id,name:c.name,status:reports.value[c.id].status}))},{name:'check_configuration',description:'Read compatibility findings for a saved configuration.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:true},execute:(input:{id:string})=>{const c=db.value.configurations.find(c=>c.id===input.id);if(!c)throw Error('Unknown configuration');return checkConfiguration(c,db.value);}}])try{await context.registerTool(tool);}catch{ /* Optional browser API. */ }}});
</script>

<template>
 <v-app><a class="skip-link" href="#main-content">Skip to main content</a>
  <aside class="sidebar" aria-label="Application navigation">
   <a class="brand" href="#" @click.prevent="navigate('Configurations')"><span class="brand-mark">b<span>.</span></span><span>bench<span class="brand-period">.</span></span></a>
   <div class="nav-label">WORKBENCH</div>
   <nav aria-label="Main navigation"><button v-for="item in navigation" :key="item.name" :class="['nav-item',{active:page===item.name}]" :aria-label="item.name" :aria-current="page===item.name?'page':undefined" @click="navigate(item.name)"><v-icon aria-hidden="true" :icon="item.icon" size="20" />{{item.name}}<span v-if="item.name==='Configurations'" class="nav-count">{{db.configurations.length}}</span></button></nav>
   <button class="nav-item data-nav" :class="{active:page==='Data & imports'}" :aria-current="page==='Data & imports'?'page':undefined" @click="navigate('Data & imports')"><v-icon aria-hidden="true" :icon="mdiDatabaseOutline" size="20" />Data & imports</button>
   <div class="sidebar-footer"><span class="status-dot" /> SQLite storage<span>v0.2</span></div>
  </aside>
  <main id="main-content" class="main" tabindex="-1" aria-label="Workspace content">
   <header class="topbar"><div>Workspace <v-icon aria-hidden="true" :icon="mdiChevronRight" size="15" /> <span>{{page}}</span><template v-if="working"><v-icon aria-hidden="true" :icon="mdiChevronRight" size="15" /><span>{{working.name}}</span></template></div><div class="local-status"><v-btn variant="text" :icon="mdiRefresh" size="small" aria-label="Reload workspace" @click="refreshWorkspace" /><span class="status-dot" />Local workspace<v-divider vertical class="mx-4" /></div></header>
   <div v-if="loading" class="loading-state"><v-progress-circular indeterminate color="primary" /><p>Opening your workbench…</p></div>
   <div v-else-if="failure" class="page-content"><v-alert type="error" role="alert" title="Cannot connect to the local server">{{failure}}<br>Start the app with pnpm dev or pnpm start.</v-alert><v-btn class="mt-4" @click="load">Retry</v-btn></div>
   <div v-else class="page-content"><v-alert v-if="recoveryRequired" type="error" role="alert" class="mb-6" title="Workspace recovery required">A disk operation could not finish safely. Edits are blocked. Stop and restart the local server to process recovery before continuing.</v-alert>
    <template v-if="working">
     <div class="detail-back"><button @click="navigate('Configurations')"><v-icon aria-hidden="true" :icon="mdiArrowLeft" size="16" />All configurations</button><span>{{dirty?'Unsaved changes':'Saved'}}</span></div>
     <div class="page-heading"><div><div class="eyebrow">CONFIGURATION BUILDER</div><h1>{{working.name}}</h1><p>Build the PC around the system it needs to run.</p></div><div class="heading-actions"><v-btn variant="outlined" :prepend-icon="mdiContentCopy" @click="duplicate(working)">Duplicate</v-btn><v-btn color="primary" :prepend-icon="mdiCheck" :loading="busy" @click="saveConfig">Save configuration</v-btn></div></div>
     <section class="builder-meta panel"><v-select v-model="working.requirementSetId" label="Installation requirements set" :items="requirementChoices" @update:model-value="selectConfigRequirements" /><v-select v-if="working.requirementSetId" v-model="working.requirementRevision" label="Pinned requirements revision" :items="requirementRevisions(working.requirementSetId)" @update:model-value="updateConfigRequirements" /><v-text-field v-model="working.name" label="Configuration name" /><v-select v-model="working.systemId" label="Equipment system" :items="[{title:'No equipment linked',value:''},...db.systems.map(s=>({title:s.name,value:s.id}))]" /><v-select v-model="working.status" label="Workflow status" :items="['Draft','In review','Approved']" /><v-text-field v-model="working.description" label="Description" class="meta-description" /></section>
     <div class="builder-grid"><div class="builder-main">
      <v-tabs v-model="detailTab" color="primary" class="content-tabs"><v-tab value="components">Components <span class="tab-count">{{working.placements.length}}</span></v-tab><v-tab value="connections">Connections</v-tab><v-tab value="storage">Storage plan</v-tab><v-tab value="checks">Compatibility</v-tab></v-tabs>
      <section v-if="detailTab==='components'" class="panel builder-section"><div class="section-head"><div><h2>Bill of materials</h2><p>Quantities are individual modules, cards or drives.</p></div><span class="neutral-badge">{{quantity(working)}} parts</span></div>
       <div class="add-component"><v-select v-model="addCategory" label="Category" :items="categories" @update:model-value="addPart=''" /><v-select v-model="addPart" label="Choose a component" :items="availableParts.map(c=>({title:c.name,value:c.id}))" /><v-text-field v-model.number="addQty" label="Qty" type="number" min="1" max="32" /><v-btn color="primary" :icon="mdiPlus" aria-label="Add component" :disabled="!addPart||!Number.isInteger(addQty)||addQty<1||addQty>32" @click="addComponent" /></div>
       <div v-if="!working.placements.length" class="empty-state"><v-icon aria-hidden="true" :icon="mdiCubeOutline" size="34" /><h3>Your build starts here</h3><p>Add a chassis, motherboard, CPU and components.</p></div>
       <div v-for="p in working.placements" :key="p.id" class="bom-row"><span class="part-icon"><v-icon aria-hidden="true" :icon="part(p.componentId)?.category==='Drive'?mdiHarddisk:mdiMemory" size="22" /></span><div class="bom-name"><small>{{part(p.componentId)?.category}}</small><strong>{{part(p.componentId)?.name||'Missing component'}}</strong><span>{{part(p.componentId)?summary(part(p.componentId)!):p.componentId}}</span></div><v-text-field v-model.number="p.quantity" label="Qty" type="number" min="1" max="32" class="qty-input" /><v-btn variant="text" :icon="mdiClose" size="small" aria-label="Remove component from build" @click="removePlacement(p.id)" /></div>
       <div v-if="selectedCards.length" class="slot-section"><h3>Expansion slot assignments</h3><p>Auto allocation checks bus, lanes and adjacent brackets. Choose a slot to reserve it.</p><div v-for="p in selectedCards" :key="p.id" class="slot-assignment"><span>{{part(p.componentId)?.name}}<v-btn v-if="p.quantity>1" size="x-small" variant="text" @click="splitPlacement(p)">Split into individual cards</v-btn></span><v-select v-model="p.slotId" :items="[{title:'Auto-assign',value:''},...slots.map(s=>({title:`${s.id} · ${s.bus} x${s.physical} / ${s.lanes} lanes`,value:s.id}))]" label="Reserved slot" /><small><span v-for="i in p.quantity" :key="i" class="d-block">Unit {{i}}: {{report?.slotAssignments[`${p.id}:${i-1}`]||'Unallocated'}}</span></small></div></div>
      </section>
      <section v-if="detailTab==='connections'" class="panel builder-section"><div class="section-head"><div><h2>Equipment connections</h2><p>{{linkedSystem?.description||'Choose an equipment system above to check required ports.'}}</p></div><v-btn v-if="linkedSystem && !working.requirementSetId" variant="outlined" size="small" @click="editSystem(linkedSystem)">Edit system</v-btn></div><template v-if="linkedSystem"><div class="port-summary"><div v-for="(total,i) in connectionPortTotals(linkedSystem.connections)" :key="i"><strong>{{total.quantity}}</strong><span>{{total.label}} required</span></div></div><div v-for="connection in linkedSystem.connections" :key="connection.id" class="connection-row"><v-icon aria-hidden="true" :icon="mdiLan" /><div><strong>{{connection.name}}</strong><p>{{connection.notes||'No additional requirements recorded.'}}</p><p v-for="requirement in connection.requirements" :key="requirement.id" class="form-hint">{{requirement.quantity}} {{portLabel(requirement)}}<template v-if="requirement.protocol"> · {{requirement.protocol}}</template><template v-if="requirement.connector"> · {{requirement.connector}}</template><template v-if="requirement.pinout"> · {{requirement.pinout}}</template></p></div><span>{{connectionSummary(connection)}}</span></div><div class="info-callout"><v-icon aria-hidden="true" :icon="mdiInformationOutline" size="19" />Counts cover dedicated physical connections. Verify connectors, protocol, pinout, bandwidth, power, isolation and required cables or converters for each device.</div></template></section>
      <section v-if="detailTab==='storage'" class="panel builder-section"><div class="section-head"><div><h2>Storage & serviceability</h2><p>Separate boot and data, then plan access and redundancy.</p></div></div><div class="storage-options"><v-select v-model="working.storage.raid" label="Data redundancy" :items="[{title:'Independent drives',value:'none'},{title:'Mirror · 2 drives',value:'mirror'},{title:'RAID 5 · 3+ drives',value:'raid5'},{title:'RAID 6 · 4+ drives',value:'raid6'},{title:'RAID 10 · even, 4+ drives',value:'raid10'}]" /><v-switch v-model="working.storage.bootMirror" label="Mirror boot drive pair" color="primary" hide-details /></div><div class="storage-capacities"><div><small>BOOT CAPACITY</small><strong>{{capacity(report?.bootGb||0)}}</strong></div><div><small>USABLE DATA CAPACITY</small><strong>{{capacity(report?.usableDataGb||0)}}</strong></div></div><div v-if="!selectedDrives.length" class="empty-state"><h3>No drives selected</h3><p>Add drives in the Components tab to begin your plan.</p></div><div v-for="p in selectedDrives" :key="p.id" class="drive-row"><div><strong>{{part(p.componentId)?.name}}</strong><small>{{p.quantity}} × {{capacity(part(p.componentId)?.specs.capacityGb||0)}}</small><v-btn v-if="p.quantity>1" size="x-small" variant="text" @click="splitPlacement(p)">Split into individual drives</v-btn></div><v-select v-model="p.role" label="Drive role" :items="['boot','data','general']" /><v-select v-model="p.mount" label="Mount / access" :items="[{title:'Automatic / onboard',value:'auto'},{title:'Internal bay',value:'internal'},{title:'Front hot-swap bay',value:'front-hot-swap'},{title:'Rear PCIe NVMe sled',value:'rear-sled'}]" /></div><div class="info-callout"><v-icon aria-hidden="true" :icon="mdiInformationOutline" size="19" />Capacity uses decimal GB/TB before filesystem overhead. Assign data drives to named redundancy groups below. Rear NVMe sleds require a selected adapter and may require bifurcation; hot-swap is vendor dependent.</div></section>
      <section v-if="detailTab==='checks'" class="panel builder-section"><div class="section-head"><div><h2>Compatibility report</h2><p>Checks update as you edit. Resolve conflicts and verify the review items.</p></div></div><div v-for="(f,i) in report?.findings" :key="i" :class="['finding',f.severity]"><v-icon aria-hidden="true" :icon="f.severity==='pass'?mdiCheckCircleOutline:mdiAlertCircleOutline" size="20" /><div><strong>{{f.title}}</strong><p>{{f.detail}}</p></div><span>{{f.severity==='error'?'Conflict':f.severity==='warning'?'Review':'Pass'}}</span></div></section>
      <section v-if="report?.storageGroups?.length" class="panel build-notes"><h3>Array capacities</h3><v-table v-workspace-table data-workspace-table="Array capacities"><thead><tr><th scope="col">ARRAY</th><th scope="col">LAYOUT</th><th scope="col">DRIVES</th><th scope="col">USABLE</th></tr></thead><tbody><tr v-for="g in report.storageGroups" :key="g.id"><td>{{g.name}}</td><td>{{g.raid}}</td><td>{{g.driveCount}}</td><td>{{capacity(g.usableGb)}}</td></tr></tbody></v-table></section><section class="panel build-notes stock-readiness"><div class="section-head"><div><h3>Stock readiness for this build</h3><p>Free, serviceable units. Reservations for other PCs are excluded.</p></div><v-btn variant="text" size="small" @click="navigate('Component inventory')">Manage stock</v-btn></div><v-table v-if="stockAvailability.length" v-workspace-table data-workspace-table="Configuration stock readiness"><thead><tr><th scope="col">COMPONENT</th><th scope="col">REQUIRED</th><th scope="col">AVAILABLE</th><th scope="col">SHORTAGE</th></tr></thead><tbody><tr v-for="row in stockAvailability" :key="row.componentId"><td>{{part(row.componentId)?.name}}</td><td>{{row.required}}</td><td>{{row.available}}</td><td :class="{'text-error':row.shortage>0}">{{row.shortage}}</td></tr></tbody></v-table><p v-else class="form-hint">Add components to see physical stock availability.</p></section>
      <section v-if="working.approvalHistory?.length" class="panel build-notes"><h3>Approved versions</h3><details v-for="version in [...working.approvalHistory].reverse()" :key="version.revision" class="my-4"><summary>Version {{version.revision}} · {{new Date(version.at).toLocaleString()}} · {{version.configuration.name}}</summary><p class="form-hint">Captured specifications and equipment requirements are preserved with this version.</p><pre class="snapshot-json" tabindex="0" role="region" aria-label="Approved configuration revision details">{{JSON.stringify(version,null,2)}}</pre></details></section><section class="panel build-notes"><EngineeringEditor :configuration="working" :db="db" /><BayEditor :configuration="working" :db="db" /><h3>Build notes</h3><v-textarea v-model="working.notes" label="Installation, drivers, verification and commissioning notes" rows="3" /></section>
     </div><aside class="build-summary" aria-label="Configuration health and capacity"><section class="panel"><div class="summary-title"><v-icon aria-hidden="true" :icon="mdiCheckCircleOutline" size="20" /><h3>Build health</h3></div><span :class="['health-badge',report?.status==='Conflicts'?'conflict':'review']">{{report?.status}}</span><p>{{report?.findings.filter(f=>f.severity==='error').length}} conflicts · {{report?.findings.filter(f=>f.severity==='warning').length}} review items</p><v-btn variant="text" color="primary" :append-icon="mdiArrowRight" class="report-link" @click="detailTab='checks'">View full report</v-btn><v-divider class="my-4" /><h4>Capacity overview</h4><div v-for="r in report?.resources" :key="r.name" class="resource"><div><span>{{r.name}}</span><strong :class="{over:r.used>r.available}">{{r.used}} / {{r.available}}{{r.unit}}</strong></div><v-progress-linear :aria-label="`${r.name} capacity used`" :model-value="r.available?Math.min(100,r.used/r.available*100):r.used?100:0" :color="r.used>r.available?'error':'primary'" height="4" rounded /></div><div class="summary-foot">Planning checks are based on catalog specifications. Review manufacturer documentation before purchasing or installing.</div></section><v-btn variant="text" color="error" :prepend-icon="mdiTrashCanOutline" @click="confirmDelete={collection:'configurations',id:working.id,name:working.name}">Delete configuration</v-btn></aside></div>
    </template>

    <template v-else-if="page==='Configurations'">
     <div class="page-heading"><div><div class="eyebrow">YOUR HARDWARE, IN HARMONY</div><h1>Configurations</h1><p>A home for every build. A clear path from parts to purpose.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="newConfig">New configuration</v-btn></div>
     <div class="overview-grid"><div class="stat-card"><div><span>Total configurations</span><v-icon aria-hidden="true" :icon="mdiDesktopTowerMonitor" size="19" /></div><strong>{{db.configurations.length.toString().padStart(2,'0')}}</strong><small>Designed for your equipment</small></div><div class="stat-card"><div><span>Components in catalog</span><v-icon aria-hidden="true" :icon="mdiMemory" size="19" /></div><strong>{{db.components.length.toString().padStart(2,'0')}}</strong><small>From chassis to scientific cards</small></div><div class="stat-card"><div><span>Connected systems</span><v-icon aria-hidden="true" :icon="mdiLan" size="19" /></div><strong>{{db.systems.length.toString().padStart(2,'0')}}</strong><small>Equipment requirements mapped</small></div><div class="stat-card attention"><div><span>Needs attention</span><v-icon aria-hidden="true" :icon="mdiAlertCircleOutline" size="19" /></div><strong>{{conflictCount.toString().padStart(2,'0')}}</strong><small>Builds with compatibility conflicts</small></div></div>
     <section class="workspace-banner"><div class="banner-illustration"><div class="tower tower-one"><i /><i /><i /><span /></div><div class="tower tower-two"><i /><i /><span /></div><div class="connection-line" /></div><div><span class="eyebrow">FROM A PC TO A COMPLETE SYSTEM</span><h2>Build with the whole bench in mind.</h2><p>Check fit, expansion slots, instrument connections and storage<br class="desktop-break"> before a single component reaches the lab.</p></div><button @click="navigate('Equipment systems')">Explore equipment systems <v-icon aria-hidden="true" :icon="mdiArrowTopRight" size="18" /></button></section>
     <div class="list-toolbar"><div class="toolbar-tabs"><button :class="{selected:filter==='All configurations'}" @click="filter='All configurations'">All configurations <span>{{db.configurations.length}}</span></button><button :class="{selected:filter==='Draft'}" @click="filter='Draft'">Drafts</button><button :class="{selected:filter==='In review'}" @click="filter='In review'">In review</button><button :class="{selected:filter==='Conflicts'}" @click="filter='Conflicts'">Conflicts</button></div><v-text-field v-model="search" placeholder="Search configurations…" :prepend-inner-icon="mdiMagnify" aria-label="Search configurations" hide-details class="search-input" /></div>
     <div class="config-grid"><article v-for="c in configs" :key="c.id" class="config-card"><div class="config-card-top"><span class="config-icon"><v-icon aria-hidden="true" :icon="mdiDesktopTowerMonitor" size="24" /></span><span :class="['workflow-badge',c.status==='In review'?'in-review':c.status==='Approved'?'approved':'']"><span />{{c.status}}</span></div><button class="card-title" @click="openConfig(c)">{{c.name}}<v-icon aria-hidden="true" :icon="mdiArrowTopRight" size="19" /></button><p class="card-description">{{c.description}}</p><div class="system-label"><v-icon aria-hidden="true" :icon="mdiLan" size="16" />{{systemName(c.systemId)}}</div><div class="card-facts"><div><small>COMPONENTS</small><strong>{{quantity(c)}} <span>parts</span></strong></div><div><small>DATA STORAGE</small><strong>{{capacity(reports[c.id]?.usableDataGb||0)}}</strong></div></div><div :class="['card-health',errors(c.id)?'has-conflicts':'']"><v-icon aria-hidden="true" :icon="errors(c.id)?mdiAlertCircleOutline:mdiCheckCircleOutline" size="17" /><span>{{errors(c.id)?`${errors(c.id)} compatibility conflicts`:'No conflicts · review required'}}</span></div><div class="card-footer"><span>Updated {{new Date(c.updatedAt).toLocaleDateString('en-US',{month:'short',day:'numeric'})}}</span><button @click="openConfig(c)">Open build <v-icon aria-hidden="true" :icon="mdiArrowRight" size="16" /></button></div></article><button class="new-build-card" @click="newConfig"><span><v-icon aria-hidden="true" :icon="mdiPlus" size="26" /></span><h3>Your next configuration</h3><p>Start with a purpose.<br>Find the right parts.</p><strong>Create a new build <v-icon aria-hidden="true" :icon="mdiArrowRight" size="16" /></strong></button></div>
     <div v-if="!configs.length" class="empty-state"><h3>No configurations found</h3><p>Try a different search or create your first build.</p></div>
     <div class="bottom-note"><v-icon aria-hidden="true" :icon="mdiInformationOutline" size="16" />Example workspace included. Verify or replace illustrative specifications before using a build.</div>
    </template>

    <template v-else-if="page==='Component catalog'">
     <div class="page-heading"><div><div class="eyebrow">THE PARTS THAT MAKE IT POSSIBLE</div><h1>Component catalog</h1><p>Dimensions, interfaces and capacity. Every detail in one place.</p></div><div class="heading-actions"><v-btn variant="outlined" :prepend-icon="mdiDownload" href="/api/export/components">Export CSV</v-btn><v-btn color="primary" :prepend-icon="mdiPlus" @click="editComponent()">Add component</v-btn></div></div>
     <div class="catalog-toolbar"><v-text-field v-model="search" placeholder="Search parts or manufacturers…" :prepend-inner-icon="mdiMagnify" aria-label="Search components" hide-details /><v-select v-model="categoryFilter" :items="['All components',...categories]" label="Category" hide-details /><span>{{components.length}} components</span></div>
     <section class="panel table-panel"><v-table v-workspace-table data-workspace-table="Component catalog"><thead><tr><th scope="col">COMPONENT</th><th scope="col">CATEGORY</th><th scope="col">SPECIFICATION SNAPSHOT</th><th scope="col">VERIFICATION</th><th scope="col">Actions</th></tr></thead><tbody><tr v-for="c in components" :key="c.id"><td><button class="table-name" @click="editComponent(c)">{{c.name}}</button><small>{{c.manufacturer||'Manufacturer not recorded'}}</small></td><td><span class="category-tag">{{c.category}}</span></td><td>{{summary(c)}}</td><td><span :class="['verification',c.verified?'verified':'']"><span />{{c.verified?'Verified':'Needs verification'}}</span></td><td><v-btn variant="text" :icon="mdiTrashCanOutline" size="small" aria-label="Delete component" @click="confirmDelete={collection:'components',id:c.id,name:c.name}" /></td></tr></tbody></v-table><div v-if="!components.length" class="empty-state"><h3>No matching components</h3><p>Add a component or adjust your filters.</p></div></section><div class="bottom-note"><v-icon aria-hidden="true" :icon="mdiInformationOutline" size="16" />Blank specification fields mean unknown, not zero. Click a component to edit its dimensions, slots and connectors.</div>
    </template>

    <template v-else-if="page==='Equipment systems'">
     <div class="page-heading"><div><div class="eyebrow">BEYOND THE COMPUTER</div><h1>Equipment systems</h1><p>Define what each PC needs to connect to and control.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="editSystem()">Add equipment system</v-btn></div><v-text-field v-model="search" placeholder="Search equipment systems…" :prepend-inner-icon="mdiMagnify" aria-label="Search equipment systems" hide-details class="system-search" />
     <div class="systems-grid"><article v-for="s in systems" :key="s.id" class="panel system-card"><div class="system-card-head"><span class="config-icon"><v-icon aria-hidden="true" :icon="mdiLan" size="25" /></span><span class="neutral-badge">{{s.connections.length}} devices</span></div><h2>{{s.name}}</h2><small>{{s.location||'Location not recorded'}}</small><p>{{s.description}}</p><div class="port-summary"><div v-for="(total,i) in connectionPortTotals(s.connections)" :key="i"><strong>{{total.quantity}}</strong><span>{{total.label}}</span></div></div><div class="device-tags"><span v-for="connection in s.connections" :key="connection.id">{{connection.name}}</span></div><div class="card-footer"><span>{{db.configurations.filter(c=>c.systemId===s.id).length}} linked builds</span><button @click="editSystem(s)">Edit requirements <v-icon aria-hidden="true" :icon="mdiArrowRight" size="16" /></button></div></article></div><div v-if="!systems.length" class="empty-state"><h3>No equipment systems found</h3><p>Add equipment and its connection requirements.</p></div>
    </template>

    <template v-else-if="page==='Installations'"><InstallationsWorkspace ref="installationsWorkspace" :db="db" :revision="revision" @reload="load" @notify="toast" @edit-pc="editPC" /></template>
    <template v-else-if="page==='PC inventory' || page==='Component inventory'">
     <InventoryWorkspace ref="inventoryWorkspace" :key="page" :db="db" :revision="revision" :mode="page==='PC inventory'?'pcs':'stock'" @reload="load" @notify="toast" @edit-pc="editPC" />
    </template>

    <template v-else-if="page==='Storage planner'">
     <div class="page-heading"><div><div class="eyebrow">CAPACITY MEETS CONTINUITY</div><h1>Storage planner</h1><p>Compare boot pairs, data redundancy and how each drive is serviced.</p></div><v-btn color="primary" :prepend-icon="mdiPlus" @click="newConfig">New configuration</v-btn></div><div class="storage-guide"><section class="panel"><v-icon aria-hidden="true" :icon="mdiHarddisk" size="25" /><h2>Front hot-swap</h2><p>Serviceable SATA bays with a compatible backplane, power and hot-plug controller.</p></section><section class="panel"><v-icon aria-hidden="true" :icon="mdiMemory" size="25" /><h2>Rear PCIe NVMe sled</h2><p>Consumes an expansion slot and lanes. May need bifurcation; live removal must be verified.</p></section><section class="panel"><v-icon aria-hidden="true" :icon="mdiServerOutline" size="25" /><h2>Boot + data pairs</h2><p>Keep system and acquisition data separate. Plan mirrored pairs and independent backups.</p></section></div><section class="panel table-panel"><v-table v-workspace-table data-workspace-table="Storage plans"><thead><tr><th scope="col">CONFIGURATION</th><th scope="col">BOOT</th><th scope="col">DATA LAYOUT</th><th scope="col">USABLE DATA</th><th scope="col">DRIVE LOCATIONS</th><th scope="col">Actions</th></tr></thead><tbody><tr v-for="c in db.configurations" :key="c.id"><td><button class="table-name" @click="openConfig(c);detailTab='storage'">{{c.name}}</button></td><td>{{c.storage.bootMirror?'Mirrored pair':'Independent'}}<small>{{capacity(reports[c.id].bootGb)}}</small></td><td>{{c.storage.raid==='none'?'Independent':c.storage.raid.toUpperCase()}}</td><td>{{capacity(reports[c.id].usableDataGb)}}</td><td><span v-for="mount in [...new Set(c.placements.filter(p=>part(p.componentId)?.category==='Drive').map(p=>p.mount))]" :key="mount" class="category-tag mr-1">{{mount}}</span></td><td><v-btn variant="text" :icon="mdiArrowTopRight" aria-label="Edit storage plan" @click="openConfig(c);detailTab='storage'" /></td></tr></tbody></v-table></section>
    </template>

    <template v-else-if="page==='Data & imports'">
     <div class="page-heading"><div><div class="eyebrow">YOUR WORK. YOUR DATA.</div><h1>Data & imports</h1><p>Local SQLite storage with portable CSV imports, exports and complete backups.</p></div><v-btn variant="outlined" :prepend-icon="mdiDownload" href="/api/backup">Download JSON backup</v-btn></div><div class="data-grid"><section class="panel data-section"><h2>Export your workspace</h2><v-switch v-model="spreadsheetSafe" label="Spreadsheet-safe exports (disable for exact round-trip)" color="primary" /><p>Each collection is stored locally in SQLite and can be exported as CSV. Nested specifications, allocations and movement history use JSON inside CSV cells.</p><a v-for="collection in ['components','systems','requirementsSets','configurations','installationLocations','pcs','inventory']" :key="collection" :href="`/api/export/${collection}?spreadsheet=${spreadsheetSafe}`" class="export-row"><v-icon aria-hidden="true" :icon="mdiDatabaseOutline" size="20" /><div><strong>{{collection}}.csv</strong><small>Editable, round-trip compatible</small></div><v-icon aria-hidden="true" :icon="mdiDownload" size="20" /></a><a :href="`/api/export/movements?spreadsheet=${spreadsheetSafe}`" class="export-row"><v-icon aria-hidden="true" :icon="mdiDownload" size="20" /><div><strong>movements.csv</strong><small>Flat inventory movement history · export only</small></div><v-icon aria-hidden="true" :icon="mdiDownload" size="20" /></a></section><section class="panel data-section"><h2>Import CSV</h2><p>New IDs are added; matching IDs are updated. Invalid rows or broken references reject the whole import.</p><v-select v-model="csvCollection" label="Collection" :items="['components','systems','requirementsSets','configurations','installationLocations','pcs','inventory']" class="mb-5" /><v-file-input v-model="importFile" label="Choose CSV file" accept=".csv,text/csv" variant="outlined" density="compact" /><v-btn color="primary" :prepend-icon="mdiUpload" :disabled="!importFile" :loading="importing" @click="importCSV">Validate & import</v-btn><small class="import-order">For workspace transfers, import components and systems, then requirements sets and configurations, then installation locations, PCs and inventory. Imports merge records; they do not remove absent records.</small></section></div><section class="panel data-section mt-6"><h2>Restore a whole workspace</h2><p>Validate all collections together before replacing data. Restoration preserves the backup’s allocations and history and saves a safety copy of the current workspace.</p><v-file-input v-model="restoreFile" label="JSON backup" accept=".json,application/json" @update:model-value="restorePreview=null" /><v-btn variant="outlined" :disabled="!restoreFile" @click="previewRestore">Validate & preview</v-btn><template v-if="restorePreview"><p class="mt-4">Replacement record counts:</p><span v-for="(count,name) in restorePreview.counts" :key="name" class="category-tag mr-2">{{name}}: {{count}}</span><v-btn color="error" class="mt-4 d-block" :loading="busy" @click="commitRestore">Restore workspace</v-btn></template></section><section class="panel source-section"><span class="config-icon"><v-icon aria-hidden="true" :icon="mdiCubeOutline" size="25" /></span><div><h2>PCPartPicker page importer</h2><p>Convert locally saved PCPartPicker product HTML containing Product JSON-LD into a component CSV. The importer extracts name, brand and source; engineering specifications need manual verification.</p><code>pnpm import:pcpartpicker ./product.html --category CPU --output ./parts.csv</code><p class="source-note">No live database crawler is included. Saved pages without structured Product data will return a clear error. See the README for supported formats.</p></div></section>
    </template>
   </div>
  </main>

  <v-dialog :model-value="!!componentDraft" @keydown.esc.stop.prevent="closeEditor('component')" aria-labelledby="component-editor-title" max-width="900" persistent @update:model-value="v=>!v&&closeEditor('component')"><v-card v-if="componentDraft" class="editor-dialog"><div class="dialog-head"><div><span class="eyebrow">COMPONENT CATALOG</span><h2 id="component-editor-title">{{db.components.some(c=>c.id===componentDraft?.id)?'Edit component':'Add component'}}</h2></div><v-btn :icon="mdiClose" variant="text" aria-label="Close component editor" @click="closeEditor('component')" /></div><div class="dialog-body"><div class="form-grid"><v-text-field v-model="componentDraft.name" label="Component name *" required :rules="[v=>!!String(v||'').trim()||'A name is required.']" /><v-select v-model="componentDraft.category" label="Category" :items="categories" @update:model-value="changeCategory" /><v-combobox :model-value="componentDraft.manufacturer" label="Manufacturer" :items="catalogSuggestions(db,'manufacturer')" :return-object="false" clearable @update:model-value="v=>componentDraft!.manufacturer=normalizeCatalogValue(v,catalogSuggestions(db,'manufacturer'))||''" /><v-text-field v-model="componentDraft.source" label="Source / manufacturer documentation URL" /></div><div class="spec-heading"><h3>Engineering specifications</h3><v-btn variant="text" size="small" @click="toggleAdvanced">{{advanced?'Use form editor':'Edit JSON'}}</v-btn></div><p class="form-hint">Leave unknown values blank. Set known absent resources to 0. Example specifications are unverified.</p><v-textarea v-if="advanced" v-model="jsonSpecs" label="Specifications JSON" rows="15" class="json-editor" /><template v-else><div class="form-grid"><template v-for="field in currentFields" :key="field.key"><v-combobox v-if="field.kind==='list'" :model-value="specListValue(field.key)" :label="field.label" :items="fieldSuggestions(field.key)" :rules="field.key==='m2Lengths'?[catalogNumericValuesRule]:[]" multiple chips closable-chips clearable :return-object="false" @update:model-value="v=>setSpec(field.key,v,field.kind)" /><v-combobox v-else-if="['socket','formFactor','memoryType'].includes(field.key)" :model-value="specText(field.key)" :label="field.label" :items="fieldSuggestions(field.key)" clearable :return-object="false" @update:model-value="v=>setSpec(field.key,v,field.kind)" /><v-select v-else-if="field.kind==='select'" :model-value="specText(field.key)" :label="field.label" :items="field.items" clearable @update:model-value="v=>setSpec(field.key,v,field.kind)" /><v-switch v-else-if="field.kind==='bool'" :model-value="!!specValue(field.key)" :label="field.label" color="primary" hide-details @update:model-value="v=>setSpec(field.key,v,'bool')" /><v-text-field v-else :model-value="specValue(field.key)" :label="field.label" :type="field.kind?'text':'number'" :min="field.kind?undefined:0" @update:model-value="v=>setSpec(field.key,v,field.kind)" /></template></div><section v-if="componentDraft.category==='Motherboard'" class="slot-editor"><div class="spec-heading"><h3>Expansion slots</h3><v-btn :prepend-icon="mdiPlus" variant="outlined" size="small" @click="addSlot">Add slot</v-btn></div><p class="form-hint">Positions count from the first rear bracket. Enter electrical lanes separately from physical connector width.</p><div v-for="(slot,i) in componentDraft.specs.slots" :key="i" class="slot-form-row"><v-text-field v-model="slot.id" label="Slot ID" /><v-select v-model="slot.bus" label="Bus" :items="['PCI','PCIe']" /><v-text-field v-model.number="slot.physical" label="Width (x)" type="number" /><v-text-field v-model.number="slot.lanes" label="Lanes" type="number" /><v-text-field v-model.number="slot.generation" label="Gen" type="number" /><v-text-field v-model.number="slot.position" label="Position" type="number" /><v-btn :icon="mdiClose" variant="text" size="small" aria-label="Remove slot" @click="componentDraft.specs.slots?.splice(i,1)" /></div></section><v-textarea v-model="componentDraft.specs.notes" label="Specification notes / restrictions" rows="2" class="mt-6" /></template><EngineeringEditor v-if="!advanced" :component="componentDraft" :db="db" /><BayEditor v-if="!advanced" :component="componentDraft" :db="db" /><v-checkbox v-model="componentDraft.verified" label="I have verified these specifications against manufacturer documentation" color="primary" hide-details /></div><div class="dialog-footer"><v-btn variant="text" @click="closeEditor('component')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!componentDraft.name.trim()||(!advanced&&catalogComponentArrayRule(componentDraft.specs)!==true)" @click="saveComponent">Save component</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!systemDraft" @keydown.esc.stop.prevent="closeEditor('system')" aria-labelledby="system-editor-title" max-width="950" persistent><v-card v-if="systemDraft" class="editor-dialog"><div class="dialog-head"><div><span class="eyebrow">EQUIPMENT REQUIREMENTS</span><h2 id="system-editor-title">{{systemDraft.name||'New equipment system'}}</h2></div><v-btn variant="text" :icon="mdiClose" aria-label="Close system editor" @click="closeEditor('system')" /></div><div class="dialog-body"><div class="form-grid"><v-text-field v-model="systemDraft.name" label="System name *" required :rules="[v=>!!String(v||'').trim()||'A name is required.']" /><v-text-field v-model="systemDraft.location" label="Location" /></div><v-textarea v-model="systemDraft.description" label="What this system controls" rows="2" class="mt-5" /><div class="spec-heading"><h3>Devices & dedicated connections</h3><v-btn variant="outlined" :prepend-icon="mdiPlus" size="small" @click="addConnection">Add device</v-btn></div><div v-for="(connection,i) in systemDraft.connections" :key="connection.id" class="connection-form"><div class="connection-form-top"><v-text-field v-model="connection.name" label="Equipment name *" /><v-text-field v-model.number="connection.usbA" label="USB-A" type="number" min="0" /><v-text-field v-model.number="connection.usbC" label="USB-C" type="number" min="0" /><v-text-field v-model.number="connection.ethernet" label="Ethernet" type="number" min="0" /><v-btn variant="text" :icon="mdiClose" size="small" aria-label="Remove equipment" @click="systemDraft.connections.splice(i,1)" /></div><v-text-field v-model="connection.notes" label="Protocol, bandwidth, power, speed, isolation or driver requirements" /></div><EngineeringEditor :system="systemDraft" :db="db" /><v-btn v-if="db.systems.some(s=>s.id===systemDraft?.id)" variant="text" color="error" :prepend-icon="mdiTrashCanOutline" @click="confirmDelete={collection:'systems',id:systemDraft.id,name:systemDraft.name};systemDraft=null">Delete equipment system</v-btn></div><div class="dialog-footer"><v-btn variant="text" @click="closeEditor('system')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!systemDraft.name.trim()" @click="saveSystem">Save requirements</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!pcDraft" @keydown.esc.stop.prevent="closeEditor('pc')" aria-labelledby="pc-editor-title" max-width="760" persistent><v-card v-if="pcDraft" class="editor-dialog"><div class="dialog-head"><h2 id="pc-editor-title">{{pcDraft.name||'Register PC'}}</h2><v-btn variant="text" :icon="mdiClose" aria-label="Close PC editor" @click="closeEditor('pc')" /></div><div class="dialog-body"><v-text-field v-model="pcDraft.name" label="PC / asset name *" required :rules="[v=>!!String(v||'').trim()||'A name is required.']" class="mb-5" /><div class="form-grid"><v-text-field v-model="pcDraft.serial" label="Serial number" /><v-text-field v-model="pcDraft.location" label="Location" /></div><v-select v-model="pcDraft.configurationId" label="Planned configuration" :items="[{title:'Unassigned',value:''},...db.configurations.map(c=>({title:c.name,value:c.id}))]" class="my-5" /><v-select v-model="pcDraft.installationLocationId" label="Physical installation location" :items="[{title:'Unassigned',value:''},...db.installationLocations.filter(l=>['Bench','System'].includes(l.kind)).map(l=>({title:locationPath(l.id,db),value:l.id}))]" class="my-5" @update:model-value="selectPCLocation" /><p class="form-hint">Installed parts are located at the assigned installation. The free-text location remains available for unregistered places and service notes.</p><v-textarea v-model="pcDraft.notes" label="Installation / asset notes" rows="2" /><div class="spec-heading"><h3>Recorded equipment & storage settings</h3><v-btn variant="outlined" size="small" :disabled="!pcDraft.configurationId" @click="captureTemplateSettings()">Copy template settings</v-btn></div><p class="form-hint">The template is a plan. Installed parts are recorded through inventory allocations. These settings are captured for this PC and do not change when the template changes.</p><v-btn v-if="!pcDraft.buildSettings" variant="outlined" @click="pcDraft.buildSettings={systemId:'',storage:{raid:'none',bootMirror:false},notes:'',portMappings:[]}">Enter build settings</v-btn><template v-else><div class="form-grid"><v-select v-model="pcDraft.buildSettings.requirementSetId" label="Recorded installation requirements set" :items="requirementChoices" @update:model-value="selectPCRequirements" /><v-select v-if="pcDraft.buildSettings.requirementSetId" v-model="pcDraft.buildSettings.requirementRevision" label="Recorded requirements revision" :items="requirementRevisions(pcDraft.buildSettings.requirementSetId)" @update:model-value="updatePCRequirements" /><v-select v-model="pcDraft.buildSettings.systemId" label="Recorded equipment system" :items="[{title:'No equipment linked',value:''},...db.systems.map(s=>({title:s.name,value:s.id}))]" /><v-select v-model="pcDraft.buildSettings.storage.raid" label="Recorded data redundancy" :items="['none','mirror','raid5','raid6','raid10']" /></div><v-switch v-model="pcDraft.buildSettings.storage.bootMirror" label="Recorded boot mirror" color="primary" hide-details /><v-textarea v-model="pcDraft.buildSettings.notes" label="Recorded configuration / driver notes" rows="2" class="mt-4" /></template><EngineeringEditor v-if="pcSettingsConfiguration" :configuration="pcSettingsConfiguration" :db="db" settings-only /><PcLifecycleEditor :pc="pcDraft" :db="db" /><v-btn v-if="db.pcs.some(p=>p.id===pcDraft?.id)" variant="text" color="error" :prepend-icon="mdiTrashCanOutline" class="mt-5" @click="confirmDelete={collection:'pcs',id:pcDraft.id,name:pcDraft.name};pcDraft=null">Delete PC</v-btn></div><div class="dialog-footer"><v-btn variant="text" @click="closeEditor('pc')">Cancel</v-btn><v-btn color="primary" :loading="busy" :disabled="!pcDraft.name.trim()" @click="savePC">Save PC</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!confirmDelete" @update:model-value="v=>!v&&(confirmDelete=null)" @keydown.esc.stop.prevent="confirmDelete=null" aria-labelledby="delete-editor-title" max-width="440"><v-card class="editor-dialog"><div class="dialog-body"><h2 id="delete-editor-title">Delete {{confirmDelete?.name}}?</h2><p class="mt-4">This removes the record from the local database. Records referenced by other records cannot be deleted.</p></div><div class="dialog-footer"><v-btn variant="text" @click="confirmDelete=null">Cancel</v-btn><v-btn color="error" :loading="busy" @click="deleteRecord">Delete</v-btn></div></v-card></v-dialog>
  <v-snackbar v-model="noticeOpen" :timeout="6000" color="primary">{{notice}}<template #actions><v-btn variant="text" @click="noticeOpen=false">Close</v-btn></template></v-snackbar>
 </v-app>
</template>
